SELECT status, shipping_fee_bucket, pct_store FROM (SELECT status, CASE WHEN shipping_fee >= 35 THEN 'high' WHEN shipping_fee >= 12 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, ROUND((100 * SUM(CASE WHEN channel = 'store' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_store FROM orders GROUP BY status, CASE WHEN shipping_fee >= 35 THEN 'high' WHEN shipping_fee >= 12 THEN 'mid' ELSE 'low' END) AS sub WHERE pct_store < 61 ORDER BY shipping_fee_bucket DESC;
